import * as assert from 'assert';

interface AuditEntry {
    from: string;
    to: string;
    ts: number;
}

class Subscription {
    static VALID_TRANSITIONS: Record<string, string[]> = {
        pending: ['active'],
        active: ['paused', 'cancelled'],
        paused: ['active', 'cancelled'],
        cancelled: []
    };

    userId: string;
    plan: string;
    state: string;
    auditLog: AuditEntry[];
    activatedAt: number | null;
    pausedAt: number | null;
    totalPausedMs: number;

    constructor(userId: string, plan: string) {
        this.userId = userId;
        this.plan = plan;
        this.state = 'pending';
        this.auditLog = [];
        this.activatedAt = null;
        this.pausedAt = null;
        this.totalPausedMs = 0;
    }

    _transition(newState: string, ts: number): void {
        const allowed = Subscription.VALID_TRANSITIONS[this.state];
        if (!allowed || !allowed.includes(newState)) {
            throw new Error(`Cannot transition from ${this.state} to ${newState}`);
        }
        this.auditLog.push({ from: this.state, to: newState, ts });
        this.state = newState;
    }

golden_completion:
activate(ts: number): void {
    this._transition('active', ts);
    this.activatedAt = ts;
}

suffix:
    pause(ts: number): void {
        this._transition('paused', ts);
        this.pausedAt = ts;
    }
}

const s1 = new Subscription('u1', 'pro');
s1.activate(1000);
assert.strictEqual(s1.state, 'active');
assert.strictEqual(s1.activatedAt, 1000);
assert.strictEqual(s1.auditLog.length, 1);
assert.deepStrictEqual(s1.auditLog[0], { from: 'pending', to: 'active', ts: 1000 });

assertions:
const s2 = new Subscription('u2', 'basic');
s2.activate(500);
assert.strictEqual(s2.state, 'active');
assert.strictEqual(s2.activatedAt, 500);

// Cannot activate again from active state
try {
    s2.activate(600);
    assert.fail('Should not allow double activation');
} catch (e: any) {
    assert.ok(e.message.includes('Cannot transition'));
}

// Cannot activate a cancelled subscription
const s3 = new Subscription('u3', 'pro');
s3.activate(100);
s3._transition('cancelled', 200);
try {
    s3.activate(300);
    assert.fail('Should not activate cancelled');
} catch (e: any) {
    assert.ok(e.message.includes('Cannot transition'));
}

