class LoanAccount {
    loanId: string;
    feesDue: number;
    interestDue: number;
    principalDue: number;
    unapplied: number;
    auditLog: PaymentLogEntry[];
    private _idempotencyKeys: Set<string>;

    constructor(loanId: string) {
        this.loanId = loanId;
        this.feesDue = 0;
        this.interestDue = 0;
        this.principalDue = 0;
        this.unapplied = 0;
        this.auditLog = [];
        this._idempotencyKeys = new Set();
    }

    addCharges(fees: number, interest: number, principal: number): void {
        this.feesDue += fees;
        this.interestDue += interest;
        this.principalDue += principal;
    }

golden_completion:
applyPayment(paymentId: string, amount: number): PaymentAllocation {
    if (this._idempotencyKeys.has(paymentId)) {
        return this.auditLog.find(e => e.paymentId === paymentId)!.applied;
    }
    this._idempotencyKeys.add(paymentId);
    let remaining = amount;
    const feePart = Math.min(remaining, this.feesDue);
    this.feesDue -= feePart;
    remaining -= feePart;
    const intPart = Math.min(remaining, this.interestDue);
    this.interestDue -= intPart;
    remaining -= intPart;
    const prinPart = Math.min(remaining, this.principalDue);
    this.principalDue -= prinPart;
    remaining -= prinPart;
    this.unapplied += remaining;
    const applied: PaymentAllocation = { fees: feePart, interest: intPart, principal: prinPart, unapplied: remaining };
    this.auditLog.push({ paymentId, amount, applied });
    return applied;
}

