import * as assert from 'assert';

interface ReleaseResult {
    released: number;
    blocked: boolean;
    reason?: string;
}

interface ReleaseLogEntry {
    milestoneId: string;
    gross: number;
    holdback: number;
    net: number;
}

class EscrowAccount {
    totalAmount: number;
    holdbackPct: number;
    released: number;
    holdback: number;
    defects: Set<string>;
    milestones: Record<string, { pct: number; released: boolean }>;
    log: ReleaseLogEntry[];
    private _processedIds: Set<string>;

    constructor(totalAmount: number, holdbackPct: number) {
        this.totalAmount = totalAmount;
        this.holdbackPct = holdbackPct;
        this.released = 0;
        this.holdback = 0;
        this.defects = new Set();
        this.milestones = {};
        this.log = [];
        this._processedIds = new Set();
    }

    registerMilestone(id: string, pct: number): void {
        this.milestones[id] = { pct, released: false };
    }

    reportDefect(defectId: string): void {
        this.defects.add(defectId);
    }

    resolveDefect(defectId: string): void {
        this.defects.delete(defectId);
    }

golden_completion:
releaseMilestone(milestoneId: string): ReleaseResult {
    if (this._processedIds.has(milestoneId)) {
        const cached = this.log.find(e => e.milestoneId === milestoneId)!;
        return { released: cached.net, blocked: false };
    }
    if (!this.milestones[milestoneId]) {
        return { released: 0, blocked: true, reason: 'not_registered' };
    }
    if (this.defects.size > 0) {
        return { released: 0, blocked: true, reason: 'defects_pending' };
    }
    const ms = this.milestones[milestoneId];
    if (ms.released) {
        return { released: 0, blocked: true, reason: 'already_released' };
    }
    const gross = this.totalAmount * ms.pct;
    const hb = gross * this.holdbackPct;
    const net = gross - hb;
    ms.released = true;
    this.released += net;
    this.holdback += hb;
    this._processedIds.add(milestoneId);
    this.log.push({ milestoneId, gross, holdback: hb, net });
    return { released: net, blocked: false };
}

suffix:
}

const escrow = new EscrowAccount(100000, 0.1);
escrow.registerMilestone('M1', 0.3);
escrow.registerMilestone('M2', 0.5);
escrow.registerMilestone('M3', 0.2);

const r1 = escrow.releaseMilestone('M1');
assert.strictEqual(r1.released, 27000);
assert.strictEqual(r1.blocked, false);
assert.strictEqual(escrow.released, 27000);
assert.strictEqual(escrow.holdback, 3000);

assertions:
// Defect blocks release
escrow.reportDefect('D1');
const r2 = escrow.releaseMilestone('M2');
assert.strictEqual(r2.blocked, true);
assert.strictEqual(r2.reason, 'defects_pending');
assert.strictEqual(escrow.released, 27000);

// Resolve defect, now M2 releases
escrow.resolveDefect('D1');
const r2b = escrow.releaseMilestone('M2');
assert.strictEqual(r2b.released, 45000);
assert.strictEqual(escrow.released, 72000);
assert.strictEqual(escrow.holdback, 8000);

// Idempotency: M1 again returns cached
const r1dup = escrow.releaseMilestone('M1');
assert.strictEqual(r1dup.released, 27000);
assert.strictEqual(r1dup.blocked, false);
assert.strictEqual(escrow.released, 72000);

// Unregistered milestone
