import * as assert from 'assert';

interface Batch {
    batchId: string;
    qty: number;
    expiresAt: number;
}

interface AllocationEntry {
    batchId: string;
    qty: number;
}

interface AllocationResult {
    success: boolean;
    allocations: AllocationEntry[];
    reason?: string;
}

class Warehouse {
    batches: Batch[];
    reservations: Record<string, AllocationEntry[]>;
    committed: Set<string>;

    constructor() {
        this.batches = [];
        this.reservations = {};
        this.committed = new Set();
    }

    receiveBatch(batchId: string, qty: number, expiresAt: number): void {
        this.batches.push({ batchId, qty, expiresAt });
        this.batches.sort((a, b) => a.expiresAt - b.expiresAt);
    }

golden_completion:
reserve(orderId: string, requestedQty: number, now: number): AllocationResult {
    if (this.reservations[orderId]) {
        return { success: true, allocations: this.reservations[orderId] };
    }
    const validBatches = this.batches.filter(b => b.expiresAt > now && b.qty > 0);
    let remaining = requestedQty;
    const allocations: AllocationEntry[] = [];
    const consumed: { idx: number; qty: number }[] = [];
    for (const batch of validBatches) {
        if (remaining <= 0) break;
        const take = Math.min(batch.qty, remaining);
        allocations.push({ batchId: batch.batchId, qty: take });
        consumed.push({ idx: this.batches.indexOf(batch), qty: take });
        remaining -= take;
    }
    if (remaining > 0) {
        return { success: false, allocations: [], reason: 'insufficient_stock' };
    }
    for (const c of consumed) {
        this.batches[c.idx].qty -= c.qty;
    }
    this.reservations[orderId] = allocations;
    return { success: true, allocations };
}

suffix:
}

const wh = new Warehouse();
wh.receiveBatch('B1', 10, 1000);
wh.receiveBatch('B2', 20, 2000);
wh.receiveBatch('B3', 5, 500);

// FEFO: B3 expires first (500), then B1 (1000), then B2 (2000)
// At now=400, all valid. Request 12: B3(5) + B1(7) = 12
const r1 = wh.reserve('O1', 12, 400);
assert.strictEqual(r1.success, true);
assert.deepStrictEqual(r1.allocations, [
    { batchId: 'B3', qty: 5 },
    { batchId: 'B1', qty: 7 }
]);

assertions:
// B3 is now 0, B1 is now 3, B2 is still 20
// At now=600, B3 is expired anyway. Request 25: B1(3) + B2(20) = 23 < 25
const r2 = wh.reserve('O2', 25, 600);
assert.strictEqual(r2.success, false);
assert.strictEqual(r2.reason, 'insufficient_stock');
// Stock unchanged after failed reservation
assert.strictEqual(wh.batches.find(b => b.batchId === 'B1')!.qty, 3);
assert.strictEqual(wh.batches.find(b => b.batchId === 'B2')!.qty, 20);

// Successful reservation of remaining stock
const r3 = wh.reserve('O3', 23, 600);
assert.strictEqual(r3.success, true);
assert.deepStrictEqual(r3.allocations, [
    { batchId: 'B1', qty: 3 },
    { batchId: 'B2', qty: 20 }
]);

// Idempotency: re-reserving O1 returns cached
const r1dup = wh.reserve('O1', 999, 400);
assert.strictEqual(r1dup.success, true);
assert.deepStrictEqual(r1dup.allocations, [
