class InventoryPlanner {
    sku: string;
    onHand: number;
    dailyDemand: number;
    leadTimeDays: number;
    safetyStockDays: number;
    orderingCost: number;
    holdingCostPerUnit: number;
    pendingOrders: ReplenishmentOrder[];
    private _cachedResults: Map<string, CheckResult>;

    constructor(config: {
        sku: string;
        onHand: number;
        dailyDemand: number;
        leadTimeDays: number;
        safetyStockDays: number;
        orderingCost: number;
        holdingCostPerUnit: number;
    }) {
        this.sku = config.sku;
        this.onHand = config.onHand;
        this.dailyDemand = config.dailyDemand;
        this.leadTimeDays = config.leadTimeDays;
        this.safetyStockDays = config.safetyStockDays;
        this.orderingCost = config.orderingCost;
        this.holdingCostPerUnit = config.holdingCostPerUnit;
        this.pendingOrders = [];
        this._cachedResults = new Map();
    }

    receiveStock(qty: number): void {
        this.onHand += qty;
    }

    consumeStock(qty: number): void {
        this.onHand = Math.max(0, this.onHand - qty);
    }

