checkReplenishment(periodId: string): CheckResult {
    if (this._cachedResults.has(periodId)) {
        return this._cachedResults.get(periodId)!;
    }
    const safetyStock = this.dailyDemand * this.safetyStockDays;
    const reorderPoint = this.dailyDemand * this.leadTimeDays + safetyStock;
    const pendingQty = this.pendingOrders.reduce((sum, o) => sum + o.qty, 0);
    const projectedStock = this.onHand + pendingQty;
    if (projectedStock > reorderPoint) {
        const result: CheckResult = { needsOrder: false };
        this._cachedResults.set(periodId, result);
        return result;
    }
    const eoq = Math.round(Math.sqrt(2 * this.dailyDemand * 365 * this.orderingCost / this.holdingCostPerUnit));
    const reason = projectedStock <= safetyStock ? 'critical' : 'reorder_point';
    const order: ReplenishmentOrder = { orderId: periodId, sku: this.sku, qty: eoq, reason };
    this.pendingOrders.push(order);
    const result: CheckResult = { needsOrder: true, order };
    this._cachedResults.set(periodId, result);
    return result;
}

