}

class CommissionEngine {
    tiers: { upTo: number; rate: number }[];
    teamBonusPct: number;
    teamQuota: number;
    annualCap: number;
    sales: SaleRecord[];
    ytdCommission: number;
    ytdClawback: number;
    private _processedDeals: Map<string, CommissionResult>;

    constructor(config: {
        tiers: { upTo: number; rate: number }[];
        teamBonusPct: number;
        teamQuota: number;
        annualCap: number;
    }) {
        this.tiers = config.tiers.sort((a, b) => a.upTo - b.upTo);
        this.teamBonusPct = config.teamBonusPct;
        this.teamQuota = config.teamQuota;
        this.annualCap = config.annualCap;
        this.sales = [];
        this.ytdCommission = 0;
        this.ytdClawback = 0;
        this._processedDeals = new Map();
    }

golden_completion:
recordSale(dealId: string, amount: number): CommissionResult {
    if (this._processedDeals.has(dealId)) {
        return this._processedDeals.get(dealId)!;
    }
    this.sales.push({ dealId, amount, refunded: false });
    let baseCommission = 0;
    let prev = 0;
    for (const tier of this.tiers) {
        if (amount <= prev) break;
        const slice = Math.min(amount, tier.upTo) - prev;
        baseCommission += slice * tier.rate;
        prev = tier.upTo;
    }
    baseCommission = Math.round(baseCommission * 100) / 100;
    const totalSales = this.sales.filter(s => !s.refunded).reduce((sum, s) => sum + s.amount, 0);
    const teamBonus = totalSales >= this.teamQuota ? Math.round(baseCommission * this.teamBonusPct * 100) / 100 : 0;
    let net = baseCommission + teamBonus;
    let cappedAt: number | null = null;
    if (this.ytdCommission + net > this.annualCap) {
        net = Math.max(0, this.annualCap - this.ytdCommission);
        cappedAt = this.annualCap;
    }
    this.ytdCommission += net;
    const result: CommissionResult = { baseCommission, teamBonus, clawback: 0, net, cappedAt };
    this._processedDeals.set(dealId, result);
    return result;
}

refundSale(dealId: string): number {
    const sale = this.sales.find(s => s.dealId === dealId && !s.refunded);
    if (!sale) return 0;
    sale.refunded = true;
    const original = this._processedDeals.get(dealId)!;
    const clawback = original.net;
    this.ytdClawback += clawback;
    this.ytdCommission -= clawback;
    return clawback;
}

