import { strict as assert } from 'assert';

interface TaxBracket {
    upTo: number;   // upper bound of bracket (Infinity for last)
    rate: number;   // marginal rate (0.0-1.0)
}

interface TaxResult {
    grossTax: number;
    credits: number;
    netTax: number;
    withheld: number;
    refundOrOwed: number;  // positive = refund, negative = owed
}

class TaxCalculator {
    private brackets: TaxBracket[];
    private standardDeduction: number;
    private results: Map<string, TaxResult> = new Map();

    constructor(brackets: TaxBracket[], standardDeduction: number) {
        this.brackets = brackets;
        this.standardDeduction = standardDeduction;
    }

    // calculate(filingId, grossIncome, credits, withheld):
    // 1. Idempotent on filingId — return cached if seen.
    // 2. Taxable income = grossIncome - standardDeduction (min 0).
    // 3. Progressive brackets: each bracket taxes income in [prevUpTo, upTo) at rate.
    //    First bracket starts at 0. grossTax is sum of bracket taxes.
    // 4. Net tax = grossTax - credits, but NEVER below zero.
    // 5. refundOrOwed = withheld - netTax (positive means refund).

golden_completion:
calculate(filingId: string, grossIncome: number, credits: number, withheld: number): TaxResult {
    if (this.results.has(filingId)) {
        return this.results.get(filingId)!;
    }
    const taxableIncome = Math.max(0, grossIncome - this.standardDeduction);
    let grossTax = 0;
    let prev = 0;
    for (const bracket of this.brackets) {
        if (taxableIncome <= prev) break;
        const taxableInBracket = Math.min(taxableIncome, bracket.upTo) - prev;
        grossTax += taxableInBracket * bracket.rate;
        prev = bracket.upTo;
    }
    grossTax = Math.round(grossTax * 100) / 100;
    const appliedCredits = Math.min(credits, grossTax);
    const netTax = grossTax - appliedCredits;
    const refundOrOwed = withheld - netTax;
    const result: TaxResult = { grossTax, credits: appliedCredits, netTax, withheld, refundOrOwed };
    this.results.set(filingId, result);
    return result;
}

