import { strict as assert } from 'assert';

interface ExpenseResult {
    approved: boolean;
    reason?: string;
    remaining: number;
    approvalLevel: string;
}

class BudgetTracker {
    private quarterlyBudget: number;
    private rolloverCapPct: number;
    private spent: number = 0;
    private rollover: number = 0;
    private frozen: boolean = false;
    private expenseLog: Map<string, ExpenseResult> = new Map();

    // Approval thresholds: amount < 1000 -> 'auto', < 5000 -> 'manager', < 20000 -> 'director', else 'vp'
    constructor(quarterlyBudget: number, rolloverCapPct: number) {
        this.quarterlyBudget = quarterlyBudget;
        this.rolloverCapPct = rolloverCapPct;
    }

    freeze(): void { this.frozen = true; }
    unfreeze(): void { this.frozen = false; }

    // submitExpense(expenseId, amount):
    // 1. Idempotent on expenseId — return cached result.
    // 2. If frozen, reject with reason 'budget_frozen'.
    // 3. Available = quarterlyBudget + rollover - spent.
    // 4. If amount > available, reject with reason 'over_budget'.
    // 5. Determine approval level based on amount thresholds.
    // 6. Deduct from budget, return result with remaining balance.

golden_completion:
submitExpense(expenseId: string, amount: number): ExpenseResult {
    if (this.expenseLog.has(expenseId)) {
        return this.expenseLog.get(expenseId)!;
    }
    if (this.frozen) {
        const r: ExpenseResult = { approved: false, reason: 'budget_frozen', remaining: this.available(), approvalLevel: 'none' };
        this.expenseLog.set(expenseId, r);
        return r;
    }
    const avail = this.available();
    if (amount > avail) {
        const r: ExpenseResult = { approved: false, reason: 'over_budget', remaining: avail, approvalLevel: 'none' };
        this.expenseLog.set(expenseId, r);
        return r;
    }
    const level = amount < 1000 ? 'auto' : amount < 5000 ? 'manager' : amount < 20000 ? 'director' : 'vp';
    this.spent += amount;
    const r: ExpenseResult = { approved: true, remaining: this.available(), approvalLevel: level };
    this.expenseLog.set(expenseId, r);
    return r;
}

private available(): number {
    return this.quarterlyBudget + this.rollover - this.spent;
}

closeQuarter(): { unspent: number; rolledOver: number } {
    const unspent = this.available();
    const rolledOver = Math.min(unspent, this.quarterlyBudget * this.rolloverCapPct);
    this.rollover = rolledOver;
    this.spent = 0;
    this.frozen = false;
    return { unspent, rolledOver };
}

