import { strict as assert } from 'assert';

interface CacheEntry<T> {
    key: string;
    value: T;
    insertedAt: number;
    lastAccessedAt: number;
    ttlMs: number;
    staleMs: number;
    refreshing: boolean;
}

interface CacheGetResult<T> {
    value: T | null;
    status: 'hit' | 'miss' | 'stale' | 'expired';
}

class CacheManager<T> {
    private capacity: number;
    private entries: Map<string, CacheEntry<T>> = new Map();
    private stats = { hits: 0, misses: 0, stales: 0, evictions: 0 };

    constructor(capacity: number) {
        this.capacity = capacity;
    }

    // put(key, value, ttlMs, staleMs, currentTime):
    // 1. If key exists, update value and reset insertedAt. Move to most-recently-used.
    // 2. If at capacity, evict the LEAST recently accessed entry (by lastAccessedAt).
    // 3. Store entry with ttlMs and staleMs (stale-while-revalidate window after TTL).

golden_completion:
put(key: string, value: T, ttlMs: number, staleMs: number, currentTime: number): void {
    if (this.entries.has(key)) {
        this.entries.delete(key);
    } else if (this.entries.size >= this.capacity) {
        let lruKey = '';
        let lruTime = Infinity;
        for (const [k, e] of this.entries) {
            if (e.lastAccessedAt < lruTime) {
                lruTime = e.lastAccessedAt;
                lruKey = k;
            }
        }
        this.entries.delete(lruKey);
        this.stats.evictions++;
    }
    this.entries.set(key, {
        key, value, insertedAt: currentTime, lastAccessedAt: currentTime,
        ttlMs, staleMs, refreshing: false
    });
}

// get(key, currentTime):
// 1. If not found: miss.
// 2. If currentTime > insertedAt + ttlMs + staleMs: expired, remove entry, miss.
// 3. If currentTime > insertedAt + ttlMs but within stale window: return value as 'stale',
//    set refreshing=true (only if not already refreshing). Update lastAccessedAt.
// 4. Otherwise: hit, update lastAccessedAt.
get(key: string, currentTime: number): CacheGetResult<T> {
    const entry = this.entries.get(key);
    if (!entry) {
        this.stats.misses++;
        return { value: null, status: 'miss' };
    }
    const age = currentTime - entry.insertedAt;
    if (age > entry.ttlMs + entry.staleMs) {
        this.entries.delete(key);
        this.stats.misses++;
        return { value: null, status: 'expired' };
    }
    if (age > entry.ttlMs) {
        entry.lastAccessedAt = currentTime;
        this.stats.stales++;
        if (!entry.refreshing) {
            entry.refreshing = true;
        }
        return { value: entry.value, status: 'stale' };
    }
    entry.lastAccessedAt = currentTime;
    this.stats.hits++;
    return { value: entry.value, status: 'hit' };
}

completeRefresh(key: string, newValue: T, currentTime: number): boolean {
    const entry = this.entries.get(key);
    if (!entry || !entry.refreshing) return false;
    entry.value = newValue;
    entry.insertedAt = currentTime;
    entry.lastAccessedAt = currentTime;
    entry.refreshing = false;
    return true;
}

getStats(): { hits: number; misses: number; stales: number; evictions: number } {
    return { ...this.stats };
}

suffix:
}

const cache = new CacheManager<string>(3);

cache.put('a', 'val-a', 1000, 500, 0);   // TTL=1s, stale=0.5s
cache.put('b', 'val-b', 2000, 1000, 0);  // TTL=2s, stale=1s
cache.put('c', 'val-c', 1000, 500, 0);

// Fresh hit
const g1 = cache.get('a', 500);
assert.equal(g1.status, 'hit');
assert.equal(g1.value, 'val-a');

// Stale (after TTL but within stale window)
const g2 = cache.get('a', 1200);
assert.equal(g2.status, 'stale');
assert.equal(g2.value, 'val-a');

assertions:
// Expired (past TTL + stale window): 1000+500=1500, time=1600
const g3 = cache.get('a', 1600);
assert.equal(g3.status, 'expired');
assert.equal(g3.value, null);

// b is still fresh at 1500
const g4 = cache.get('b', 1500);
assert.equal(g4.status, 'hit');
assert.equal(g4.value, 'val-b');

// LRU eviction: capacity=3, a was removed (expired), so only b,c remain
// Add d, no eviction needed since size=2
cache.put('d', 'val-d', 1000, 500, 2000);

// Add e -> need to evict. c was last accessed at time 0, b at 1500, d at 2000 -> evict c
cache.put('e', 'val-e', 1000, 500, 2500);
const g5 = cache.get('c', 2500);
assert.equal(g5.status, 'miss');  // c was evicted

// b still there
const g6 = cache.get('b', 2500);
assert.equal(g6.status, 'stale');  // 2500 > 0+2000=2000 -> stale

// Refresh b
const refreshed = cache.completeRefresh('b', 'val-b-new', 2600);
assert.equal(refreshed, true);
const g7 = cache.get('b', 2700);
assert.equal(g7.status, 'hit');
assert.equal(g7.value, 'val-b-new');

// Stats check
const stats = cache.getStats();
assert.equal(stats.hits, 3);     // g1, g4, g7
assert.equal(stats.stales, 2);   // g2, g6
assert.equal(stats.evictions, 1); // c evicted
assert.equal(stats.misses, 2);   // g3(expired), g5(evicted)

