// GC2 has 15 left. Take 15, remaining=15.
assert.strictEqual(r3.success, false);
assert.strictEqual(r3.amountCharged, 15);
assert.strictEqual(r3.remainingOrderBalance, 15);
assert.strictEqual(r3.cardBalances['GC2'], 0);
assert.strictEqual(gcs.cards.get('GC2')!.redeemed, true);

// Unknown card
