// GC999 unknown (-1), GC1 redeemed (balance 0) => no valid cards
assert.strictEqual(r4.success, false);
assert.strictEqual(r4.cardBalances['GC999'], -1);
assert.strictEqual(r4.cardBalances['GC1'], 0);
assert.strictEqual(r4.amountCharged, 0);

assert.strictEqual(gcs.redemptions.length, 3);  // ORD1(GC1,GC2) + ORD2(GC2)

