import * as assert from 'assert';

interface LeaveBalance {
    annual: number;
    sick: number;
    carryover: number;  // annual leave carried from last year
}

interface LeaveRequest {
    reqId: string;
    empId: string;
    type: 'annual' | 'sick';
    days: number;
    status: 'pending' | 'approved' | 'denied';
}

interface LeaveResult {
    approved: boolean;
    reason?: string;
    balanceAfter?: LeaveBalance;
}

class LeaveManager {
    balances: Map<string, LeaveBalance> = new Map();
    requests: Map<string, LeaveRequest> = new Map();
    maxCarryover: number;
    sickLeaveRequiresDoc: number;  // sick leave > this many days requires documentation

    constructor(maxCarryover: number, sickLeaveRequiresDoc: number) {
        this.maxCarryover = maxCarryover;
        this.sickLeaveRequiresDoc = sickLeaveRequiresDoc;
    }

    addEmployee(empId: string, annual: number, sick: number, carryover: number): void {
        // Cap carryover at maxCarryover
        this.balances.set(empId, { annual, sick, carryover: Math.min(carryover, this.maxCarryover) });
    }

    // requestLeave(reqId, empId, type, days, hasDocumentation):
    // 1. Idempotent: if reqId exists, return current status
    // 2. Employee must exist
    // 3. For 'sick' leave with days > sickLeaveRequiresDoc and !hasDocumentation:
    //    deny with reason 'documentation_required'
    // 4. Check balance:
    //    - 'sick': just check sick balance >= days
    //    - 'annual': deduct from CARRYOVER first, then annual.
    //      Total available = carryover + annual. Must be >= days.
    // 5. If insufficient: deny with reason 'insufficient_balance'
    // 6. Deduct:
    //    - 'sick': sick -= days
    //    - 'annual': deduct min(carryover, days) from carryover,
    //      remainder from annual
    // 7. Store request with status 'approved'. Return approved=true with balanceAfter.

golden_completion:
requestLeave(reqId: string, empId: string, type: 'annual' | 'sick',
              days: number, hasDocumentation: boolean = false): LeaveResult {
    if (this.requests.has(reqId)) {
        const existing = this.requests.get(reqId)!;
        return { approved: existing.status === 'approved', reason: 'duplicate_request' };
    }
    const bal = this.balances.get(empId);
    if (!bal) {
        return { approved: false, reason: 'unknown_employee' };
    }
    if (type === 'sick' && days > this.sickLeaveRequiresDoc && !hasDocumentation) {
        this.requests.set(reqId, { reqId, empId, type, days, status: 'denied' });
        return { approved: false, reason: 'documentation_required' };
    }
    if (type === 'sick') {
        if (bal.sick < days) {
            this.requests.set(reqId, { reqId, empId, type, days, status: 'denied' });
            return { approved: false, reason: 'insufficient_balance' };
        }
        bal.sick -= days;
    } else {
        const totalAvail = bal.carryover + bal.annual;
        if (totalAvail < days) {
            this.requests.set(reqId, { reqId, empId, type, days, status: 'denied' });
            return { approved: false, reason: 'insufficient_balance' };
        }
        const fromCarryover = Math.min(bal.carryover, days);
        bal.carryover -= fromCarryover;
        bal.annual -= (days - fromCarryover);
    }
    this.requests.set(reqId, { reqId, empId, type, days, status: 'approved' });
    return { approved: true, balanceAfter: { ...bal } };
}

