interface CreditEvent {
    type: 'payment_ontime' | 'payment_late' | 'default' | 'inquiry' | 'account_opened';
    timestamp: number;  // months since account creation
    amount?: number;
}

interface ScoreBreakdown {
    paymentHistory: number;
    creditUtilization: number;
    accountAge: number;
    inquiryPenalty: number;
    rawScore: number;
    tier: string;
}

class CreditScorer {
    events: CreditEvent[] = [];
    creditLimit: number;
    currentBalance: number;
    accountOpenedAt: number;  // month 0
    decayFactor: number;      // older events count less: weight * decay^(age in months)

    // Tier thresholds: score >= 750 'excellent', >= 650 'good', >= 550 'fair', else 'poor'
    constructor(creditLimit: number, decayFactor: number) {
        this.creditLimit = creditLimit;
        this.currentBalance = 0;
        this.accountOpenedAt = 0;
        this.decayFactor = decayFactor;
    }

    addEvent(event: CreditEvent): void {
        this.events.push(event);
        if (event.type === 'account_opened' && event.amount) {
            this.currentBalance += event.amount;
        }
    }

    setBalance(balance: number): void {
        this.currentBalance = balance;
    }

    // Calculate credit score at a given month.
    // Payment history (max 400 pts): each on-time = +20*decay, late = -30*decay, default = -80*decay
    // Credit utilization (max 300 pts): ratio = balance/limit.
    //   ratio <= 0.1: 300, <= 0.3: 250, <= 0.5: 200, <= 0.7: 100, else 50
    // Account age (max 100 pts): min(currentMonth - accountOpenedAt, 120) / 120 * 100
    // Inquiry penalty: each inquiry in last 6 months = -10
    // Raw score = paymentHistory (capped 0..400) + utilization + accountAge - inquiryPenalty (floor 0)
    // Score cannot exceed 800 or go below 300.

golden_completion:
calculateScore(currentMonth: number): ScoreBreakdown {
    // Payment history
    let paymentRaw = 0;
    for (const e of this.events) {
        const age = currentMonth - e.timestamp;
        const decay = Math.pow(this.decayFactor, age);
        if (e.type === 'payment_ontime') paymentRaw += 20 * decay;
        else if (e.type === 'payment_late') paymentRaw -= 30 * decay;
        else if (e.type === 'default') paymentRaw -= 80 * decay;
    }
    const paymentHistory = Math.max(0, Math.min(400, Math.round(paymentRaw * 100) / 100));

    // Credit utilization
    const ratio = this.creditLimit > 0 ? this.currentBalance / this.creditLimit : 0;
    let creditUtilization: number;
    if (ratio <= 0.1) creditUtilization = 300;
    else if (ratio <= 0.3) creditUtilization = 250;
    else if (ratio <= 0.5) creditUtilization = 200;
    else if (ratio <= 0.7) creditUtilization = 100;
    else creditUtilization = 50;

    // Account age
    const ageMonths = Math.min(currentMonth - this.accountOpenedAt, 120);
    const accountAge = Math.round(ageMonths / 120 * 100 * 100) / 100;

    // Inquiry penalty
    let inquiryPenalty = 0;
    for (const e of this.events) {
        if (e.type === 'inquiry' && currentMonth - e.timestamp <= 6) {
            inquiryPenalty += 10;
        }
    }

    let rawScore = paymentHistory + creditUtilization + accountAge - inquiryPenalty;
    rawScore = Math.max(300, Math.min(800, Math.round(rawScore * 100) / 100));

    let tier: string;
    if (rawScore >= 750) tier = 'excellent';
    else if (rawScore >= 650) tier = 'good';
    else if (rawScore >= 550) tier = 'fair';
    else tier = 'poor';

    return { paymentHistory, creditUtilization, accountAge, inquiryPenalty, rawScore, tier };
}

suffix:
}

