        const it=p.items as {sku:string;qty:number;price:number}[];
        if (!it||!it.length) return {ok:false,err:'empty'};
        if (it.some((x:any)=>x.qty<=0)) return {ok:false,err:'bad_qty'};
        this.data.set(id,{items:[...it],total:it.reduce((s:number,x:any)=>s+x.qty*x.price,0),status:'open',ver:this.nv(id)});
