    const o=this.data.get(id);
    if (!o) return {ok:false,err:'missing'};
    if (type==='cancel') {
        if (o.status==='cancelled') return {ok:false,err:'already'};
        o.status='cancelled'; o.ver=this.nv(id); return {ok:true};
